7	// ====== 模态对话框 ======
8	function showModal({ title, body, buttons }) {
9	  const overlay = document.createElement("div");
10	  overlay.className = "modal-overlay";
11	
12	  const box = document.createElement("div");
13	  box.className = "modal-box";
14	  box.innerHTML = `
15	    <h2>${title}</h2>
16	    <div class="modal-body">${body}</div>
17	    <div class="modal-actions"></div>
18	  `;
19	
20	  const actionsDiv = box.querySelector(".modal-actions");
21	  for (const btn of buttons) {
22	    const btnEl = document.createElement("button");
23	    btnEl.className = "btn " + (btn.cls || "btn-primary");
24	    btnEl.textContent = btn.text;
25	    btnEl.addEventListener("click", () => {
26	      document.body.removeChild(overlay);
27	      if (btn.callback) btn.callback();
28	    });
29	    actionsDiv.appendChild(btnEl);
30	  }
31	
32	  overlay.appendChild(box);
33	  overlay.addEventListener("click", (e) => {
34	    if (e.target === overlay) document.body.removeChild(overlay);
35	  });
36	  document.body.appendChild(overlay);
37	}
