395	function renderActionsTab(state, parent) {
396	  const actions = getAvailableActions(state);
397	
398	  // 分离出行和其他行动
399	  const travelActions = actions.filter((a) => a.id.startsWith("travel_"));
400	  const housingActions = actions.filter(
401	    (a) => a.id.startsWith("housing_") || a.id.startsWith("storage_"),
402	  );
403	  const otherActions = actions.filter(
404	    (a) =>
405	      !a.id.startsWith("travel_") &&
406	      !a.id.startsWith("housing_") &&
407	      !a.id.startsWith("storage_"),
408	  );
409	
410	  // === 🌍 出行区域（置顶，醒目） ===
411	  if (travelActions.length > 0) {
412	    const travelSection = document.createElement("div");
413	    travelSection.style.cssText = "margin-bottom:16px;";
414	    travelSection.innerHTML =
415	      '<h3 style="color:var(--accent);margin-bottom:8px;font-size:14px;">🌍 出行 — 点击前往其他地点</h3>';
416	
417	    const travelGrid = document.createElement("div");
418	    travelGrid.className = "action-cards";
419	    travelGrid.style.gridTemplateColumns =
420	      "repeat(auto-fill, minmax(180px, 1fr))";
421	
422	    for (const action of travelActions) {
423	      const destKey = action.id.replace("travel_", "");
424	      const dest =
425	        typeof getLocation === "function" ? getLocation(destKey) : null;
426	      const jobCount = dest ? (dest.jobs || []).length : 0;
427	
428	      // 服务标签
429	      const badges =
430	        typeof getLocationServiceBadges === "function"
431	          ? getLocationServiceBadges(destKey)
432	          : [];
433	      const badgeStr =
434	        badges.length > 0
435	          ? badges
436	              .map(
437	                (b) =>
438	                  `<span style="font-size:9px;padding:2px 5px;border-radius:3px;background:${b.bg};color:${b.color};border:1px solid ${b.color};">${b.icon} ${b.label}</span>`,
439	              )
440	              .join(" ")
441	          : "";
