1290	    const bankRate = isNewbie ? 0.002 : 0.001;
1291	    const bankInterest = Math.floor(state.resources.bankBalance * bankRate);
1292	    if (bankInterest > 0) state.resources.bankBalance += bankInterest;
1293	  }
1294	
1295	  // 每3天更新价格
1296	  if (state.player.day - state.trade.lastPriceUpdate >= 3) {
1297	    if (typeof updateAllPrices === "function") updateAllPrices(state);
1298	  }
1299	
1300	  // 投资每日tick
1301	  if (typeof tickInvestmentDaily === "function") tickInvestmentDaily(state);
1302	
1303	  // 天气更新
