1355	function checkLoseConditions(state) {
1356	  if (state.status.health <= 0) {
1357	    state.flags.gameOver = true;
1358	    state.flags.gameOverReason = "健康耗尽，你倒在了这座城市的街头...";
1359	    showGameOverModal();
1360	    return;
1361	  }
1362	  if (state.resources.debt > 50000) {
1363	    state.flags.gameOver = true;
1364	    state.flags.gameOverReason = "债务超过5万元，讨债的人找上门来...";
1365	    showGameOverModal();
1366	    return;
1367	  }
1368	  // 职场失败条件
1369	  if (
1370	    state.player.phase === "corporate" &&
1371	    typeof checkCorpLoseConditions === "function"
1372	  ) {
1373	    if (checkCorpLoseConditions(state)) return;
1374	  }
1375	}
